update public.content_variants set body = $json${"text":"An MLM sells vitamins at a reasonable price. Members can sell products without having to recruit. Commissions are earned from product sales. This is closer to product-based MLM."}$json$::jsonb where id = 'bbcb7f2c-d5e4-4460-915a-f6e360377557';
update public.content_variants set body = $json${"text":"Characteristics of fraudulent investments: guaranteed high returns, no risk, time pressure, and invite-a-friend schemes. Legitimate investments do not promise guaranteed profits."}$json$::jsonb where id = 'bbd3ab75-8868-48c9-b2a1-7a795e2e9b12';
update public.content_variants set body = $json${"text":"Index mutual funds that follow IDX30 automatically provide diversification into 30 large stocks. This is suitable for beginners who don't have time to research one by one.","source_ids":["c7c57d03-733f-4fe8-bd15-ce3a1cd4a760"]}$json$::jsonb where id = 'bc066666-f10c-4937-8a5c-a176906aac55';
